// CSD_RATIONALE_BEGIN
// This strategy tracks the visible output (`generated`), whether we are
// currently inside an arithmetic-computation span (`insideConstrainedOut`), and
// the active constrained contents (`currentConstrainedOut`). Outside spans it
// generates mostly freely, but it also watches for a small set of arithmetic
// cue tokens and can proactively open a visible `<< >>` span after such a cue.
// Inside spans it keeps the parser as the hard authority and uses adaptive,
// group-aware constrained decoding so arithmetic-like tokens are softly
// preferred while parser validity is preserved. Completing a constrained prefix
// triggers an explicit close of the visible span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity: In the outside-span chunk branch, `insideConstrainedOut`
//   stays false unless the chunk already ended with `<<`; in that case we call
//   EnterObservedConstrainedSpan, which sets `currentConstrainedOut := []`,
//   valid by the precondition `parser.IsValidPrefix([])`. In the proactive-open
//   branch, OpenConstrainedSpan also sets the constrained prefix to `[]`, so the
//   invariant holds immediately after opening.
// parser_validity: In the close branch, CloseConstrainedSpan exits constrained
//   mode, so `insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)`
//   becomes vacuous. In the active constrained decoding branches,
//   AdaptiveConstrainedStep and SafePenalizedConstrainedStep return either EOS
//   or a token preserving parser validity; on the non-EOS path,
//   AppendConstrainedToken updates `currentConstrainedOut` to that valid
//   extension, preserving the invariant.
// progress: The outside chunk branch increases `steps` by `stepsUsed`, and the
//   returned `generated` grows by at most that many visible tokens, so
//   `|generated| <= |generatedPrefix| + steps` is preserved. The proactive-open
//   and close branches each consume one forced-delimiter step and append at most
//   one visible token, so the same bound is preserved.
// progress: Each inside-span token branch consumes exactly one step and appends
//   at most one visible token on the non-EOS path; if EOS is returned, `steps`
//   still increases by one while visible output does not grow. Therefore every
//   branch preserves `|generated| <= |generatedPrefix| + steps`.
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;
var arithmeticCueSeen: bool := false;
var cueTokens: seq<Token> := ["=", "+", "-", "*", "/", "x", "compute", "total", "sum"];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if arithmeticCueSeen {
      var openedGenerated, openedInside, openedCurrent := helpers.OpenConstrainedSpan(lm, generated);
      generated := openedGenerated;
      insideConstrainedOut := openedInside;
      currentConstrainedOut := openedCurrent;
      arithmeticCueSeen := false;
      steps := steps + 1;
    } else {
      var remainingChunk: nat := maxSteps - steps;
      var chunkBudget: nat := if remainingChunk > 3 then 3 else remainingChunk;
      var chunkedGenerated, stoppedOnOpenSpan, stoppedOnEos, stepsUsed := helpers.UnconstrainedChunk(
        lm, prompt, generated, chunkBudget, "<<", eosToken
      );
      generated := chunkedGenerated;
      steps := steps + stepsUsed;

      if stoppedOnEos {
        break;
      } else if stoppedOnOpenSpan {
        var enteredGenerated, enteredInside, enteredCurrent := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := enteredGenerated;
        insideConstrainedOut := enteredInside;
        currentConstrainedOut := enteredCurrent;
        arithmeticCueSeen := false;
      } else {
        var prevEq, foundEq := helpers.LastTokenBefore(generated, ">>");
        if foundEq {
          if prevEq == "=" || prevEq == "+" || prevEq == "-" || prevEq == "*" || prevEq == "/" {
            arithmeticCueSeen := true;
          } else {
            arithmeticCueSeen := false;
          }
        } else {
          arithmeticCueSeen := false;
        }
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var closedGenerated, closedInside, closedCurrent := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := closedGenerated;
    insideConstrainedOut := closedInside;
    currentConstrainedOut := closedCurrent;
    arithmeticCueSeen := false;
    steps := steps + 1;
  } else {
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    var constrainedPrompt := prompt + stablePrefix;
    var next := eosToken;
    var eqCount := helpers.CountTokenOccurrences(currentConstrainedOut, "=");
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 12);
    if eqCount == 0 && !narrow {
      next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, 12, eosToken
      );
    } else {
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, [">>"], 4.0, eosToken
      );
    }
    steps := steps + 1;

    if next == eosToken {
      break;
    } else {
      var appendedGenerated, appendedInside, appendedCurrent := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := appendedGenerated;
      insideConstrainedOut := appendedInside;
      currentConstrainedOut := appendedCurrent;
    }
  }
}

cost := steps;
